"""The ``stockroom`` command line."""

from __future__ import annotations

import csv
import io
import json
import os
import re
import sys
from typing import Dict, List, Optional, Tuple

from .catalog import parse_catalog
from .fulfil import order_status, plan_fulfil, shipped_basket, shipped_so_far
from .movements import parse_date, parse_movements
from .orders import parse_orders
from .pricing import format_money, price_order
from .shelves import buy_quantity, format_delta, history, status, stock_levels
from .textio import ParseError

USAGE = """\
usage: stockroom COMMAND [ARGS] [--dir DIR]

  stockroom stock [--json]
  stockroom low [--json]
  stockroom history SKU [--json]
  stockroom receive DATE SKU QUANTITY [NOTE]
  stockroom ship DATE SKU QUANTITY [NOTE]
  stockroom quote ORDER [--json]
  stockroom fulfil ORDER DATE
  stockroom invoice ORDER [--json]
  stockroom report [--format text|csv|json]
"""

# command -> (minimum positionals, maximum positionals, allowed options)
COMMANDS = {
    "stock": (0, 0, ("--json",)),
    "low": (0, 0, ("--json",)),
    "history": (1, 1, ("--json",)),
    "receive": (3, 4, ()),
    "ship": (3, 4, ()),
    "quote": (1, 1, ("--json",)),
    "fulfil": (2, 2, ()),
    "invoice": (1, 1, ("--json",)),
    "report": (0, 0, ("--format",)),
}
LITERAL_COMMANDS = ("receive", "ship", "fulfil")
SHELF_COMMANDS = ("stock", "low", "history", "receive", "ship")
FORMATS = ("text", "csv", "json")


class UsageError(Exception):
    """Exit 2: something is wrong with the command line."""


class FileProblem(Exception):
    """Exit 2: a file or folder cannot be read."""


class Refusal(Exception):
    """Exit 1: a data mistake or a refused request."""


class Args:
    def __init__(self, command: str, positionals: List[str], directory: str,
                 json_output: bool, fmt: str):
        self.command = command
        self.positionals = positionals
        self.directory = directory
        self.json = json_output
        self.format = fmt


def parse_args(argv: List[str]) -> Args:
    """Hand-rolled parser: ``--dir`` anywhere; options spelled in full."""
    directory = "."
    rest: List[str] = []
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if token.startswith("--dir="):
            directory = token[len("--dir="):]
            i += 1
            continue
        rest.append(token)
        i += 1

    command_index = None
    for index, token in enumerate(rest):
        if not token.startswith("-") or token == "-":
            command_index = index
            break
    if command_index is None:
        if rest:
            raise UsageError("unknown option %s" % rest[0])
        raise UsageError("no command given")
    command = rest[command_index]
    if command not in COMMANDS:
        raise UsageError("unknown command %s" % command)
    minimum, maximum, allowed = COMMANDS[command]

    before = rest[:command_index]
    after = rest[command_index + 1:]
    json_output = False
    fmt = "text"
    positionals: List[str] = []
    if command in LITERAL_COMMANDS:
        if before:
            raise UsageError("unknown option %s" % before[0])
        positionals = after
    else:
        tokens = before + after
        j = 0
        while j < len(tokens):
            token = tokens[j]
            if token.startswith("-") and token != "-":
                if token == "--json" and "--json" in allowed:
                    json_output = True
                elif token == "--format" and "--format" in allowed:
                    if j + 1 >= len(tokens):
                        raise UsageError("option --format needs a value")
                    fmt = tokens[j + 1]
                    j += 1
                elif token.startswith("--format=") and "--format" in allowed:
                    fmt = token[len("--format="):]
                else:
                    raise UsageError("unknown option %s" % token)
            else:
                positionals.append(token)
            j += 1
        if fmt not in FORMATS:
            raise UsageError("bad --format value %r (text, csv or json)" % fmt)

    if not minimum <= len(positionals) <= maximum:
        raise UsageError("wrong number of arguments for %s" % command)
    if command in ("receive", "ship") and parse_date(positionals[0]) is None:
        raise UsageError("bad date %r (expected a real YYYY-MM-DD date)" % positionals[0])
    if command == "fulfil" and parse_date(positionals[1]) is None:
        raise UsageError("bad date %r (expected a real YYYY-MM-DD date)" % positionals[1])
    return Args(command, positionals, directory, json_output, fmt)


# ---------------------------------------------------------------- files


def read_file(directory: str, name: str, required: bool) -> Optional[str]:
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise FileProblem("%s: file not found" % name)
        return None
    except OSError as error:
        raise FileProblem("%s: cannot read: %s" % (name, error.strerror or error))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise FileProblem("%s: not valid UTF-8" % name)


def parse_file(name, parser, *args):
    try:
        return parser(*args)
    except ParseError as error:
        error.filename = name
        raise Refusal(str(error))


class World:
    """The parsed files a command needs."""

    def __init__(self, args: Args):
        directory = args.directory
        if not directory or not os.path.isdir(directory):
            raise FileProblem("%s: folder not found" % (directory or "''"))
        command = args.command
        need_movements = command in SHELF_COMMANDS or command in ("fulfil", "invoice", "report")
        need_orders = command in ("quote", "fulfil", "invoice", "report")
        catalog_text = read_file(directory, "catalog.txt", True)
        movements_text = read_file(directory, "movements.txt", False) if need_movements else None
        orders_text = read_file(directory, "orders.txt", False) if need_orders else None
        self.directory = directory
        self.movements_text = movements_text or ""
        self.catalog = parse_file("catalog.txt", parse_catalog, catalog_text)
        self.movements = []
        self.orders = []
        if need_movements:
            self.movements = parse_file("movements.txt", parse_movements,
                                        self.movements_text, self.catalog)
        if need_orders:
            self.orders = parse_file("orders.txt", parse_orders, orders_text or "", self.catalog)

    def find_order(self, text: str):
        wanted = text.upper()
        for order in self.orders:
            if order.id == wanted:
                return order
        raise Refusal("unknown order %s" % text)

    def refusal_text(self, error: ParseError, lines: List[str]) -> str:
        """Word a refused append so it never names a line that is not in movements.txt."""
        text = self.movements_text
        existing = text.count("\n") + (0 if not text or text.endswith("\n") else 1)
        # Everything before " (below zero)" is the part that names the SKU and balance.
        problem = error.reason.split(" (below zero)")[0]
        if error.line > existing:
            added = lines[min(error.line - existing, len(lines)) - 1]
            return "refused: %s on %s" % (problem, added.split(" ")[0])
        return ("refused: the new movement would take stock below zero at existing "
                "movements.txt line %d: %s after that line" % (error.line, problem))

    def append_movements(self, lines: List[str]) -> None:
        """Append lines to movements.txt after checking the whole file still parses."""
        separator = "" if not self.movements_text or self.movements_text.endswith("\n") else "\n"
        addition = separator + "".join(line + "\n" for line in lines)
        try:
            parse_movements(self.movements_text + addition, self.catalog)
        except ParseError as error:
            raise Refusal(self.refusal_text(error, lines))
        path = os.path.join(self.directory, "movements.txt")
        try:
            with open(path, "ab") as handle:
                handle.write(addition.encode("utf-8"))
        except OSError as error:
            raise FileProblem("movements.txt: cannot write: %s" % (error.strerror or error))


# ------------------------------------------------------------- output


def dump_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


def cmd_stock(args: Args, world: World) -> str:
    levels = stock_levels(world.catalog, world.movements)
    rows = []
    for sku, onhand in levels.items():
        product = world.catalog[sku]
        rows.append((sku, product.name, onhand, status(onhand, product.reorder)))
    if args.json:
        return dump_json([{"sku": s, "name": n, "onhand": o, "status": t} for s, n, o, t in rows])
    return lines_out(["%s %d %s %s" % (s, o, t, n) for s, n, o, t in rows])


def cmd_low(args: Args, world: World) -> str:
    levels = stock_levels(world.catalog, world.movements)
    rows = []
    for sku, onhand in levels.items():
        reorder = world.catalog[sku].reorder
        if status(onhand, reorder) != "ok":
            rows.append((sku, onhand, reorder, buy_quantity(onhand, reorder)))
    if args.json:
        return dump_json([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows])
    return lines_out(["%s %d %d %d" % row for row in rows])


def cmd_history(args: Args, world: World) -> str:
    sku = args.positionals[0].upper()
    if sku not in world.catalog:
        raise Refusal("unknown SKU %s" % args.positionals[0])
    entries = history(sku, world.movements)
    if args.json:
        return dump_json([
            {"date": e.date.isoformat(), "delta": format_delta(e.delta),
             "balance": e.balance, "note": e.note}
            for e in entries
        ])
    out = []
    for e in entries:
        line = "%s %s %d" % (e.date.isoformat(), format_delta(e.delta), e.balance)
        out.append(line + (" " + e.note if e.note else ""))
    return lines_out(out)


def parse_quantity_text(text: str) -> Optional[int]:
    """A whole number of 1 or more, or None (also for text past the int conversion limit)."""
    if not re.fullmatch(r"[0-9]+", text, re.ASCII):
        return None
    try:
        value = int(text)
    except ValueError:
        return None
    return value if value >= 1 else None


def cmd_move(args: Args, world: World) -> str:
    date_text, sku_text, quantity_text = args.positionals[:3]
    note = args.positionals[3].strip(" \t") if len(args.positionals) == 4 else ""
    sku = sku_text.upper()
    if sku not in world.catalog:
        raise Refusal("unknown SKU %s" % sku_text)
    quantity = parse_quantity_text(quantity_text)
    if quantity is None:
        shown = quantity_text if len(quantity_text) <= 40 else quantity_text[:40] + "..."
        raise Refusal("bad quantity %r (a whole number of 1 or more, no sign)" % shown)
    if "\n" in note or "\r" in note:
        raise Refusal("a note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise Refusal("note is not valid UTF-8")
    signed = quantity if args.command == "receive" else -quantity
    line = "%s %s %s" % (date_text, sku, format_delta(signed))
    if note:
        line += " " + note
    world.append_movements([line])
    return line + "\n"


def quote_object(order, quote) -> Dict:
    return {
        "order": order.id,
        "date": order.date.isoformat(),
        "customer": order.customer,
        "lines": [
            {"sku": l.sku, "quantity": l.quantity, "unit": format_money(l.unit),
             "gross": format_money(l.gross), "discount": format_money(l.discount),
             "net": format_money(l.net)}
            for l in quote.lines
        ],
        "subtotal": format_money(quote.subtotal),
        "order_discount": format_money(quote.order_discount),
        "tax": format_money(quote.tax),
        "total": format_money(quote.total),
    }


def quote_text(order, quote, prefix: str = "") -> str:
    out = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for l in quote.lines:
        out.append("%s %d %s %s %s %s" % (
            l.sku, l.quantity, format_money(l.unit), format_money(l.gross),
            format_money(l.discount), format_money(l.net)))
    out.append("subtotal " + format_money(quote.subtotal))
    out.append("order discount " + format_money(quote.order_discount))
    out.append("tax " + format_money(quote.tax))
    out.append("total " + format_money(quote.total))
    return lines_out(out)


def cmd_quote(args: Args, world: World) -> str:
    order = world.find_order(args.positionals[0])
    quote = price_order(order, world.catalog)
    if args.json:
        return dump_json(quote_object(order, quote))
    return quote_text(order, quote)


def cmd_invoice(args: Args, world: World) -> str:
    order = world.find_order(args.positionals[0])
    shipped = shipped_so_far(order, world.movements)
    basket = shipped_basket(order, shipped)
    if not basket.lines:
        raise Refusal("nothing has shipped for %s" % order.id)
    quote = price_order(basket, world.catalog)
    if args.json:
        return dump_json(quote_object(order, quote))
    return quote_text(order, quote, "invoice ")


def cmd_fulfil(args: Args, world: World) -> str:
    order = world.find_order(args.positionals[0])
    date_text = args.positionals[1]
    date = parse_date(date_text)
    if date < order.date:
        raise Refusal("%s is dated %s; cannot fulfil on %s" % (order.id, order.date.isoformat(), date_text))
    shipped = shipped_so_far(order, world.movements)
    plan = plan_fulfil(order, date, world.movements)
    additions = ["%s %s -%d order %s" % (date_text, p.sku, p.shipped, order.id)
                 for p in plan if p.shipped > 0]
    if additions:
        world.append_movements(additions)
    after = {p.sku: shipped[p.sku] + p.shipped for p in plan}
    out = ["%s shipped %d backordered %d" % (p.sku, p.shipped, p.backordered) for p in plan]
    out.append("status " + order_status(order, after))
    return lines_out(out)


def cmd_report(args: Args, world: World) -> str:
    rows = []
    for order in sorted(world.orders, key=lambda o: (o.date, o.id)):
        shipped = shipped_so_far(order, world.movements)
        basket = shipped_basket(order, shipped)
        invoiced = price_order(basket, world.catalog).total if basket.lines else None
        quoted = price_order(order, world.catalog).total
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped.values()),
            "quoted": format_money(quoted),
            "invoiced": format_money(invoiced) if invoiced is not None else "0.00",
        })
    if args.format == "json":
        return dump_json(rows)
    if args.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"])
        for r in rows:
            writer.writerow([r["order"], r["date"], r["customer"], r["status"], r["ordered"],
                             r["shipped"], r["quoted"], r["invoiced"]])
        return buffer.getvalue()
    return lines_out([
        "%s %s %s %s %d/%d %s %s" % (r["order"], r["date"], r["customer"], r["status"],
                                     r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    ])


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def _write_stdout(text: str) -> None:
    if sys.stdout is None:
        # File descriptor 1 was closed (>&-): nobody is listening, same as a closed pipe.
        return
    try:
        sys.stdout.buffer.write(text.encode("utf-8"))
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        # The reader went away: stop quietly, with status 0.
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except OSError:
            pass


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parse_args(list(argv))
    except UsageError as error:
        sys.stderr.write("stockroom: %s\n%s" % (error, USAGE))
        return 2
    try:
        world = World(args)
        output = HANDLERS[args.command](args, world)
    except FileProblem as error:
        sys.stderr.write("stockroom: %s\n" % error)
        return 2
    except Refusal as error:
        sys.stderr.write("stockroom: %s\n" % error)
        return 1
    _write_stdout(output)
    return 0

